/* AQUIFER RUN — game flow (originally PC4, rebuilt by PC1): title → world map → level → report.
 * Engine/physics: engine.js + player.js (PC4). Rules: systems.js. Art: art.js. Levels: levels/*.json
 * (generated by tools/make_run_levels.py from data/global/atlas.json).
 */
(function () {
  'use strict';
  var LEVELS = [
    { id: 'tulare', name: 'Tulare Basin', place: 'California, USA', biome: 'tulare', lon: -119.3, lat: 36.1 },
    { id: 'eloy', name: 'Eloy', place: 'Arizona, USA', biome: 'eloy', lon: -111.6, lat: 32.8 },
    { id: 'konya', name: 'Karapınar', place: 'Konya, Türkiye', biome: 'konya', lon: 33.5, lat: 37.7 },
    { id: 'mexico', name: 'Mexico City', place: 'Mexico', biome: 'mexico', lon: -99.1, lat: 19.4 }
  ];
  var ATLAS_ID = { tulare: 'central_valley', eloy: 'eloy', konya: 'konya_plain', mexico: 'mexico_city' };
  var STORAGE_KEY = 'aquifer_run_progress_v2', SETTINGS_KEY = 'aquifer_run_settings_v1', STORY_KEY = 'aquifer_run_story_seen';
  function openPage(url) { try { window.open(url, '_blank', 'noopener'); } catch (e) { location.href = url; } }

  var canvas = document.getElementById('gameCanvas'), ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = true;
  var Engine = window.RunEngine, Player = window.RunPlayer, Sys = window.RunSystems, Art = window.RunArt;
  var T = Engine.SCALED_TILE, W = Engine.VIEW_W, H = Engine.VIEW_H;

  // ---------- settings / progress ----------
  var settings = { sound: true, reducedMotion: false };
  try { var ss = JSON.parse(localStorage.getItem(SETTINGS_KEY) || 'null'); if (ss) { settings.sound = ss.sound !== false; settings.reducedMotion = !!ss.reducedMotion; } } catch (e) {}
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) settings.reducedMotion = true;
  function saveSettings() { try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); } catch (e) {} }
  function loadProgress() { try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}') || {}; } catch (e) { return {}; } }
  function saveStars(id, n) { var p = loadProgress(); if (n > (p[id] || 0)) { p[id] = n; try { localStorage.setItem(STORAGE_KEY, JSON.stringify(p)); } catch (e) {} } }
  function isUnlocked(i) { return i === 0 || (loadProgress()[LEVELS[i - 1].id] || 0) > 0; }

  // ---------- sound ----------
  var audioCtx = null;
  function beep(freq, dur, type, vol) {
    if (!settings.sound) return;
    try {
      if (!audioCtx) { var AC = window.AudioContext || window.webkitAudioContext; if (!AC) return; audioCtx = new AC(); }
      if (audioCtx.state === 'suspended') audioCtx.resume();
      var o = audioCtx.createOscillator(), g = audioCtx.createGain();
      o.type = type || 'square'; o.frequency.value = freq; g.gain.setValueAtTime(vol || 0.05, audioCtx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + (dur || 0.1)); o.connect(g); g.connect(audioCtx.destination); o.start(); o.stop(audioCtx.currentTime + (dur || 0.1));
    } catch (e) {}
  }
  function jingle(notes) { notes.forEach(function (n, i) { setTimeout(function () { beep(n, 0.12, 'triangle', 0.05); }, i * 110); }); }

  // ---------- input (keyboard/gamepad from engine + touch buttons + tap on canvas) ----------
  var input = Engine.createInput();
  var isTouch = window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
  if (isTouch) document.body.classList.add('has-touch');
  window.addEventListener('touchstart', function () { isTouch = true; document.body.classList.add('has-touch'); }, { once: true, passive: true });
  Array.prototype.forEach.call(document.querySelectorAll('.t-btn[data-key]'), function (btn) {
    var key = btn.getAttribute('data-key');
    function down(e) { e.preventDefault(); btn.classList.add('active'); input.setTouch(key, true); }
    function up(e) { e.preventDefault(); btn.classList.remove('active'); input.setTouch(key, false); }
    btn.addEventListener('touchstart', down, { passive: false }); btn.addEventListener('touchend', up, { passive: false });
    btn.addEventListener('touchcancel', up, { passive: false }); btn.addEventListener('mousedown', down);
    btn.addEventListener('mouseup', up); btn.addEventListener('mouseleave', up);
  });
  var tapQueued = null;   // {x,y} in game coordinates, for menus
  canvas.addEventListener('pointerdown', function (e) {
    var r = canvas.getBoundingClientRect(); tapQueued = { x: (e.clientX - r.left) * W / r.width, y: (e.clientY - r.top) * H / r.height };
    canvas.focus && canvas.focus();
  });
  function takeTap() { var t = tapQueued; tapQueued = null; return t; }
  function keyName(k) { if (!isTouch) return k; return { 'SPACE': 'JUMP', 'E': 'ACTION', '←': '◀', '→': '▶' }[k] || k; }

  // ---------- level data (preloaded so the map can show real NISAR numbers) ----------
  var levelData = {};
  function fetchLevel(id) {
    if (levelData[id]) return Promise.resolve(levelData[id]);
    return fetch('levels/' + id + '.json').then(function (r) { if (!r.ok) throw new Error('missing'); return r.json(); })
      .then(function (j) { levelData[id] = j; return j; });
  }

  var scenes = Engine.createSceneManager(), L = null;

  // ---------- button rows for menus (← → to choose, SPACE/E to press, or click/tap) ----------
  function makeMenu() { return { sel: 0, rects: [], pl: true, pr: true }; }
  function menuUpdate(mn, items, inp, tap) {
    if (inp.left && !mn.pl) { mn.sel = (mn.sel + items.length - 1) % items.length; beep(380, 0.05); }
    if (inp.right && !mn.pr) { mn.sel = (mn.sel + 1) % items.length; beep(420, 0.05); }
    mn.pl = inp.left; mn.pr = inp.right;
    if (tap) { for (var i = 0; i < mn.rects.length; i++) { var r = mn.rects[i]; if (tap.x >= r.x && tap.x <= r.x + r.w && tap.y >= r.y && tap.y <= r.y + r.h) { mn.sel = i; return items[i]; } } return null; }
    if (inp.jumpPressed || inp.actionPressed) return items[mn.sel];
    return null;
  }
  function menuDraw(c, mn, items, y, t, dark, noHint) {
    c.font = '800 19px "Baloo 2", sans-serif';
    var gap = 14, ws = items.map(function (it) { return Math.max(150, c.measureText(it.label).width + 44); });
    var total = ws.reduce(function (a, b) { return a + b; }, 0) + gap * (items.length - 1), x = W / 2 - total / 2;
    mn.rects = [];
    items.forEach(function (it, i) {
      var on = i === mn.sel, w = ws[i], lift = on ? Math.sin(t * 6) * 2 : 0;
      Art.card(c, x, y - lift, w, 46, { bg: on ? '#ffd23f' : (dark ? 'rgba(20,26,44,.82)' : '#ffffff'), r: 23, flat: !on, border: '#1c2233' });
      Art.text(c, it.label, x + w / 2, y + 10 - lift, { size: 19, align: 'center', color: on ? '#1c2233' : (dark ? '#ffffff' : '#1c2233'), shadow: false });
      mn.rects.push({ x: x, y: y, w: w, h: 46 }); x += w + gap;
    });
    if (noHint) return;
    var hint = isTouch ? 'Tap a button' : '← → choose   ·   SPACE press';
    Art.text(c, hint, W / 2, y + 54, { size: 13, align: 'center', color: dark ? '#ffffff' : '#6b7286', outline: dark ? 3 : 0, outlineColor: '#1c2233', shadow: false });
  }

  // ---------- TITLE ----------
  var titleT = 0, titleMenu = makeMenu();
  function storySeen() { try { return localStorage.getItem(STORY_KEY) === '1'; } catch (e) { return false; } }
  var TITLE_ITEMS = [
    { label: '▶  PLAY', go: function () { scenes.go(storySeen() ? 'map' : 'story', { next: 'map' }); } },
    { label: 'Why does ground sink?', go: function () { scenes.go('story', { next: 'title' }); } },
    { label: 'Real NISAR map ↗', go: function () { openPage('../atlas.html'); } }
  ];
  scenes.register('title', {
    enter: function () { titleT = 0; titleMenu.sel = 0; titleMenu.pl = titleMenu.pr = true; },
    update: function (dt, inp) {
      titleT += dt; var tap = takeTap(); if (titleT < 0.3) return;
      var it = menuUpdate(titleMenu, TITLE_ITEMS, inp, tap);
      if (it) { beep(560, 0.1, 'triangle'); it.go(); }
    },
    draw: function (c) {
      Art.title(c, W, H, titleT, { menu: true, subtitle: 'A NASA satellite sees valleys sinking. Help stop it!' });
      Art.card(c, 14, 12, 170, 30, { bg: 'rgba(20,26,44,.75)', r: 15, flat: true });
      Art.text(c, 'NISAR Vision game', 99, 17, { size: 14, align: 'center', color: '#ffffff', shadow: false });
      menuDraw(c, titleMenu, TITLE_ITEMS, 352, titleT, true);
      Art.text(c, 'Real places, real numbers: NASA-ISRO NISAR radar data, 2026  ·  Team Aseltech  ·  NASA Space Apps 2026', W / 2, H - 24, { size: 12, align: 'center', color: '#fff6e0', outline: 3, outlineColor: '#4a2e18', shadow: false });
    }
  });

  // ---------- STORY: why the ground sinks, in three pictures ----------
  var story = null, storyT = 0, storyMenu = makeMenu();
  var STORY_PANELS = [
    { title: '1. Seen from space', lines: ['NISAR is a radar satellite', 'from NASA and ISRO. Every', '12 days it measures the', 'ground to the centimetre.'] },
    { title: '2. Too much pumping', lines: ['Wells pull water out from', 'under the ground faster than', 'rain refills it. The clay is', 'squeezed: the ground sinks.'] },
    { title: '3. Your job', lines: ['Switch pumps OFF, water', 'crops with rain, grab NISAR', 'data chips, and keep the', 'water above the safe line.'] }
  ];
  function drawStoryArt(c, i, x, y, w, h, t) {
    c.save(); c.beginPath(); c.rect(x, y, w, h); c.clip();
    if (i === 0) {
      var g = c.createLinearGradient(0, y, 0, y + h); g.addColorStop(0, '#0e1a3a'); g.addColorStop(1, '#2c4f86'); c.fillStyle = g; c.fillRect(x, y, w, h);
      for (var k = 0; k < 18; k++) { c.fillStyle = 'rgba(255,255,255,' + (0.3 + 0.5 * ((k * 37) % 7) / 7) + ')'; c.fillRect(x + (k * 53) % w, y + (k * 29) % (h - 40), 2, 2); }
      c.fillStyle = '#6aa84f'; c.fillRect(x, y + h - 26, w, 26); c.fillStyle = '#8a5a34'; c.fillRect(x, y + h - 10, w, 10);
      var sx = x + w / 2 + Math.sin(t) * 40, sy = y + 34;
      c.globalAlpha = 0.25 + 0.15 * Math.sin(t * 5); c.fillStyle = '#fff3a0'; c.beginPath(); c.moveTo(sx - 6, sy + 10); c.lineTo(sx - 60, y + h - 26); c.lineTo(sx + 60, y + h - 26); c.lineTo(sx + 6, sy + 10); c.fill(); c.globalAlpha = 1;
      Art.drawSatellite(c, sx, sy, 0.6);
      for (var d = 0; d < 5; d++) { c.fillStyle = d === 2 ? '#e8483c' : '#f0a23a'; c.beginPath(); c.arc(sx - 40 + d * 20, y + h - 22, 4, 0, 7); c.fill(); }
    } else if (i === 1) {
      var lvl = 0.75 - 0.45 * ((t * 0.25) % 1), sink = 14 * ((t * 0.25) % 1);
      c.fillStyle = '#bfe3ff'; c.fillRect(x, y, w, h);
      c.fillStyle = '#7a4e2c'; c.fillRect(x, y + 50 + sink, w, h);
      c.fillStyle = '#6aa84f'; c.fillRect(x, y + 44 + sink, w, 8);
      var ay = y + 70 + sink, ah = h - 74 - sink;
      c.fillStyle = '#2f8fe6'; c.fillRect(x + 10, ay + ah * (1 - lvl), w - 20, ah * lvl);
      c.strokeStyle = '#ffd23f'; c.lineWidth = 3; c.setLineDash([8, 6]); c.beginPath(); c.moveTo(x + 6, ay + ah * 0.55); c.lineTo(x + w - 6, ay + ah * 0.55); c.stroke(); c.setLineDash([]);
      c.strokeStyle = '#3a4458'; c.lineWidth = 5; c.beginPath(); c.moveTo(x + 60, y + 50 + sink); c.lineTo(x + 60, ay + ah - 6); c.stroke();
      Art.drawSprite(c, 'pump_on', Math.floor(t * 3), x + 36, y + 6 + sink, false);
      c.strokeStyle = '#e8483c'; c.lineWidth = 4; c.beginPath(); c.moveTo(x + w - 40, y + 14); c.lineTo(x + w - 40, y + 42); c.stroke();
      c.fillStyle = '#e8483c'; c.beginPath(); c.moveTo(x + w - 50, y + 38); c.lineTo(x + w - 30, y + 38); c.lineTo(x + w - 40, y + 50); c.fill();
      Art.text(c, 'sinks', x + w - 40, y + 52 + sink, { size: 12, align: 'center', color: '#ffffff', outline: 3, outlineColor: '#7a1f16', shadow: false });
    } else {
      c.fillStyle = '#cfeeff'; c.fillRect(x, y, w, h); c.fillStyle = '#6aa84f'; c.fillRect(x, y + h - 30, w, 30); c.fillStyle = '#8a5a34'; c.fillRect(x, y + h - 12, w, 12);
      Art.drawSprite(c, 'pump_off', 0, x + 14, y + h - 78, false);
      Art.drawSprite(c, 'nisa_action', Math.floor(t * 3), x + 66, y + h - 114, false);
      Art.drawSprite(c, 'crop_green', 0, x + 128, y + h - 78, false);
      Art.drawSprite(c, 'chip', Math.floor(t * 6), x + w - 60, y + h - 110 + Math.sin(t * 4) * 4, false);
      Art.drawSprite(c, 'drop', Math.floor(t * 6), x + w - 108, y + h - 120 + Math.sin(t * 4 + 1) * 4, false);
    }
    c.restore();
  }
  scenes.register('story', {
    enter: function (p) { story = p || { next: 'map' }; storyT = 0; storyMenu.sel = 0; storyMenu.pl = storyMenu.pr = true; },
    update: function (dt, inp) {
      storyT += dt; var tap = takeTap(); if (storyT < 0.8) return;
      var items = [{ label: story.next === 'map' ? "Let's go!  ▶" : 'Back' }];
      if (menuUpdate(storyMenu, items, inp, tap)) { try { localStorage.setItem(STORY_KEY, '1'); } catch (e) {} beep(600, 0.12, 'triangle'); scenes.go(story.next); }
    },
    draw: function (c) {
      Art.drawBackground(c, 'tulare', storyT * 20, W, H, storyT);
      c.fillStyle = 'rgba(10,14,28,.62)'; c.fillRect(0, 0, W, H);
      Art.text(c, 'Why is the ground sinking?', W / 2, 18, { size: 34, align: 'center', color: '#fff', outline: 7 });
      var cw = 284, gap = 18, x0 = (W - (cw * 3 + gap * 2)) / 2;
      STORY_PANELS.forEach(function (p, i) {
        var pop = Math.min(1, Math.max(0, (storyT - i * 0.35) * 3)); if (pop <= 0) return;
        var x = x0 + i * (cw + gap), y = 78 + (1 - pop) * 24; c.globalAlpha = pop;
        Art.card(c, x, y, cw, 330, { bg: '#fff7e8', r: 18 });
        drawStoryArt(c, i, x + 12, y + 12, cw - 24, 160, storyT);
        Art.text(c, p.title, x + cw / 2, y + 184, { size: 21, align: 'center', color: '#1c2233', shadow: false });
        p.lines.forEach(function (ln, k) { Art.text(c, ln, x + cw / 2, y + 216 + k * 24, { size: 16, align: 'center', color: '#3a4458', shadow: false }); });
        c.globalAlpha = 1;
      });
      for (var a = 0; a < 2 && storyT > 0.8; a++) Art.text(c, '→', x0 + (a + 1) * cw + a * gap + gap / 2, 228, { size: 30, align: 'center', color: '#ffd23f', outline: 5 });
      Art.text(c, 'These valleys are real. How fast each one sinks comes from our NISAR Vision atlas.', W / 2, 420, { size: 15, align: 'center', color: '#ffd23f', shadow: false });
      if (storyT > 0.8) menuDraw(c, storyMenu, [{ label: story.next === 'map' ? "Let's go!  ▶" : 'Back' }], 448, storyT, true);
    }
  });

  // ---------- WORLD MAP (our real atlas map) ----------
  var mapIdx = 0, mapCool = 0, mapT = 0;
  function pins() {
    var prog = loadProgress();
    return LEVELS.map(function (lv, i) {
      var d = levelData[lv.id];
      return { id: lv.id, name: lv.name + ', ' + lv.place.split(',')[0], lon: lv.lon, lat: lv.lat,
        rate: d && d.nisar ? d.nisar.realFactCm : null, stars: prog[lv.id] || 0, locked: !isUnlocked(i) };
    });
  }
  scenes.register('map', {
    enter: function () { mapCool = 0.25; mapT = 0; },
    update: function (dt, inp) {
      mapT += dt; mapCool = Math.max(0, mapCool - dt);
      if (mapCool <= 0) {
        if (inp.left && mapIdx > 0) { mapIdx--; mapCool = 0.18; beep(360, 0.05); }
        if (inp.right && mapIdx < LEVELS.length - 1) { mapIdx++; mapCool = 0.18; beep(400, 0.05); }
      }
      var tap = takeTap();
      if (tap && tap.y > 330) {          // tap on a level card
        var cw = (W - 40 - 3 * 14) / 4, k = Math.floor((tap.x - 20) / (cw + 14));
        if (k >= 0 && k < 4) { if (k === mapIdx) { if (isUnlocked(k)) startLevel(k); } else { mapIdx = k; beep(400, 0.05); } return; }
      }
      if ((inp.jumpPressed || inp.actionPressed) && mapCool <= 0) {
        if (isUnlocked(mapIdx)) { beep(600, 0.12, 'triangle'); startLevel(mapIdx); } else beep(160, 0.15, 'sawtooth');
      }
    },
    draw: function (c) {
      Art.worldMap(c, W, H, mapT, pins(), LEVELS[mapIdx].id);
      window.RunTouch = isTouch;
    }
  });

  function startLevel(idx, skipBrief) {
    fetchLevel(LEVELS[idx].id).then(function (json) { scenes.go(skipBrief ? 'level' : 'howto', { idx: idx, json: json }); })
      .catch(function () { scenes.go('map'); });
  }

  // ---------- HOW TO PLAY (shown before every valley; 4 picture cards + this valley's goal) ----------
  var brief = null, briefT = 0;
  var CARDS = [
    { icon: 'drop', title: 'Raindrop', lines: ['Run into it:', '+1 water in your tank', '(blue boxes, top left).'] },
    { icon: 'pump_on', title: 'Pump (a well)', lines: ['It pulls water OUT', 'of the ground. Stand at it', 'and press E to switch it OFF.'] },
    { icon: 'crop_dry', title: 'Thirsty crop', lines: ['Press E to give it', '1 water from your tank.', 'Saved farms pump less.'] },
    { icon: 'bar', title: 'Water underground', lines: ['Keep the blue ABOVE', 'the yellow line, or the', 'ground sinks for good.'] }
  ];
  scenes.register('howto', {
    enter: function (p) { brief = p; briefT = 0; },
    update: function (dt, inp) { briefT += dt; if (briefT > 0.6 && (inp.jumpPressed || inp.actionPressed || takeTap())) { beep(600, 0.12, 'triangle'); scenes.go('level', brief); } },
    draw: function (c) {
      var j = brief.json, ent = j.entities || [];
      Art.drawBackground(c, j.biome, briefT * 25, W, H, briefT);
      c.fillStyle = 'rgba(10,14,28,.62)'; c.fillRect(0, 0, W, H);
      Art.text(c, (brief.idx + 1) + '. ' + j.name, W / 2, 18, { size: 34, align: 'center', color: '#fff', outline: 7 });
      Art.text(c, 'How to play', W / 2, 64, { size: 18, align: 'center', color: '#ffd23f', shadow: false });
      var cw = 206, gap = 14, x0 = (W - (cw * 4 + gap * 3)) / 2;
      CARDS.forEach(function (cd, i) {
        var x = x0 + i * (cw + gap), y = 100, pop = Math.min(1, Math.max(0, (briefT - i * 0.12) * 4));
        c.globalAlpha = pop;
        Art.card(c, x, y + (1 - pop) * 20, cw, 236, { bg: '#fff7e8', r: 18 });
        Art.text(c, String(i + 1), x + 16, y + 10, { size: 22, color: '#2f8fe6', shadow: false });
        if (cd.icon === 'bar') {
          c.fillStyle = '#5a3a22'; c.fillRect(x + 38, y + 38, cw - 76, 64);
          c.fillStyle = '#2f8fe6'; c.fillRect(x + 38, y + 38 + 64 * 0.35, cw - 76, 64 * 0.65);
          c.strokeStyle = '#ffd23f'; c.lineWidth = 4; c.setLineDash([10, 6]); c.beginPath(); c.moveTo(x + 32, y + 38 + 64 * 0.6); c.lineTo(x + cw - 32, y + 38 + 64 * 0.6); c.stroke(); c.setLineDash([]);
        } else { c.save(); c.translate(x + cw / 2 - 36, y + 30); c.scale(1.5, 1.5); Art.drawSprite(c, cd.icon, Math.floor(briefT * 4), 0, 0, false); c.restore(); }
        Art.text(c, cd.title, x + cw / 2, y + 112, { size: 20, align: 'center', color: '#1c2233', shadow: false });
        cd.lines.forEach(function (ln, k) { Art.text(c, ln, x + cw / 2, y + 144 + k * 24, { size: 15, align: 'center', color: '#3a4458', shadow: false }); });
        c.globalAlpha = 1;
      });
      var pumps = ent.filter(function (e) { return e.type === 'pump'; }).length, crops = ent.filter(function (e) { return e.type === 'crop'; }).length;
      Art.card(c, x0, 356, cw * 4 + gap * 3, 108, { bg: 'rgba(20,26,44,.9)', r: 18 });
      Art.text(c, 'Your goal in this valley', W / 2, 366, { size: 16, align: 'center', color: '#9fd0ff', shadow: false });
      Art.text(c, 'Switch off ' + pumps + ' pumps  ·  save ' + crops + ' crops  ·  reach the flag', W / 2, 390, { size: 22, align: 'center', color: '#fff', shadow: false });
      if (j.intro) Art.text(c, j.intro, W / 2, 426, { size: 15, align: 'center', color: '#ffd23f', shadow: false });
      if (Math.floor(briefT * 2) % 2) Art.text(c, isTouch ? 'Tap to start' : 'Press SPACE to start', W / 2, 486, { size: 22, align: 'center', color: '#fff', outline: 6 });
    }
  });

  // ---------- LEVEL ----------
  var levelSceneObj = {
    enter: function (payload) {
      if (payload && payload.resume && L) return;          // back from pause: keep the run
      var json = payload.json;
      if (json.radar && Art.loadRadar) Art.loadRadar(json.biome, json.radar);
      var sp = json.spawn || { x: 2, y: 6 };
      L = {
        idx: payload.idx, json: json, tileMap: Engine.createTileMap(json), sys: Sys.createLevelState(json),
        entities: (json.entities || []).map(function (e, i) {
          return { id: i, type: e.type, x: e.x * T, y: e.y * T, startX: e.x * T, w: T, h: T, range: (e.range || 3) * T, dir: 1,
            fact: e.fact || null, line: e.line || '', active: true, off: false, watered: false, calmed: false, calmT: 0, said: false };
        }),
        player: Player.createPlayer(sp.x * T, sp.y * T - 16), camera: Engine.createCamera(W, H),
        time: 0, scanTimer: Math.min(12, (json.nisar && json.nisar.scanEverySec) || 22), scanActive: 0, scans: 0,
        toasts: [], fx: [], floats: [], tips: (json.tips || []).map(function (t) { return Object.assign({ done: false, shownT: 0 }, t); }),
        jumpedOnce: false, spawnX: sp.x * T, legend: idx0(payload.idx)
      };
      L.player.checkpointX = L.player.x; L.player.checkpointY = L.player.y;
    },
    update: function (dt, inp) {
      if (!L) return;
      if (inp.pausePressed) { scenes.go('pause'); return; }
      L.time += dt;
      var P = L.player, S = L.sys;

      // NISAR radar pass
      L.scanTimer -= dt;
      if (L.scanTimer <= 0) {
        L.scanTimer = (L.json.nisar && L.json.nisar.scanEverySec) || 22; L.scanActive = 3.5; L.scans++;
        beep(740, 0.08, 'sine'); beep(980, 0.1, 'sine');
        if (L.scans === 1) toast('NISAR is passing! Its radar shows the real 2026 map of where this valley is sinking.', 'science', 5);
      }
      if (L.scanActive > 0) L.scanActive = Math.max(0, L.scanActive - dt);

      var pr = Player.updatePlayer(P, inp, L.tileMap, dt, Engine);
      if (pr.jumped) { beep(420, 0.07, 'square', 0.03); L.jumpedOnce = true; }
      var events = [];

      if (P.y > L.tileMap.pixelHeight + 60) {               // fell into a pit
        P.hearts -= 1; beep(160, 0.25, 'sawtooth'); events.push({ type: 'fall' });
        if (P.hearts <= 0) { toast('Out of hearts! Try again: catch rain and switch pumps off sooner.', 'warn', 4); startLevel(L.idx, true); return; }
        P.x = P.checkpointX; P.y = P.checkpointY; P.vx = 0; P.vy = 0; P.invulnTimer = 1.2; L.camera.triggerShake(5, 0.25);
      }

      for (var i = 0; i < L.entities.length; i++) {
        var e = L.entities[i]; if (!e.active) continue;
        if (e.type === 'dust') {
          if (e.calmed) { e.calmT -= dt; if (e.calmT <= 0) e.calmed = false; }
          else { e.x += e.dir * 80 * dt; if (e.x > e.startX + e.range) e.dir = -1; if (e.x < e.startX - e.range) e.dir = 1; }
        }
        var reach = (e.type === 'pump' || e.type === 'crop' || e.type === 'farmer') ? 24 : 0;
        var hit = P.x < e.x + e.w + reach && P.x + P.w > e.x - reach && P.y < e.y + e.h && P.y + P.h > e.y - (e.type === 'farmer' ? 36 : 0);
        if (!hit) continue;
        if (e.type === 'drop' || e.type === 'chip') {
          e.active = false; beep(e.type === 'chip' ? 880 : 660, 0.1, 'triangle');
          events.push({ type: 'pickup', target: e.type, fact: e.fact });
          addFx('sparkle', e.x + T / 2, e.y + T / 2);
          if (e.type === 'drop') flt('+1 water', P.x + P.w / 2, P.y - 10, '#2f8fe6');
        } else if (e.type === 'checkpoint') {
          P.checkpointX = e.x; P.checkpointY = e.y - P.h + T; e.active = false; beep(580, 0.1, 'sine'); toast('Checkpoint saved', 'info', 1.6);
        } else if (e.type === 'dust' && !e.calmed) {
          if (inp.actionPressed) { e.calmed = true; e.calmT = 4; beep(500, 0.12, 'triangle'); events.push({ type: 'action', target: 'dust', entity: e }); addFx('splash', e.x + T / 2, e.y + T / 2); }
          else if (P.invulnTimer <= 0) { P.invulnTimer = 1.0; L.camera.triggerShake(4, 0.2); beep(200, 0.15, 'sawtooth'); events.push({ type: 'dustHit' }); addFx('dust', e.x + T / 2, e.y + T); flt('-3 water', P.x + P.w / 2, P.y - 10, '#c8321f'); }
        } else if (e.type === 'flag') {
          events.push({ type: 'reachFlag' }); Sys.update(S, dt, events);
          var res = Sys.score(S), n = res.stars.filter(Boolean).length; saveStars(L.json.id, n);
          jingle([523, 659, 784, 1047]); scenes.go('report', { levelIdx: L.idx, json: L.json, result: res }); return;
        } else if (inp.actionPressed) {
          if (e.type === 'pump' && !e.off) { e.off = true; beep(320, 0.12, 'square'); events.push({ type: 'action', target: 'pump', entity: e }); L.camera.triggerShake(2, 0.12); flt('Pump OFF!  +4 water underground', e.x + T / 2, e.y - 20, '#1f9a50'); }
          else if (e.type === 'crop' && !e.watered) { e.watered = true; beep(640, 0.12, 'sine'); events.push({ type: 'action', target: 'crop', entity: e }); addFx('splash', e.x + T / 2, e.y + T / 2); }
          else if (e.type === 'farmer' && e.line) { toast('Farmer: “' + e.line + '”', 'info', 4); }
        }
        if (e.type === 'farmer' && e.line && !e.said) { e.said = true; toast('Farmer: “' + e.line + '”', 'info', 4); }
      }

      S.playerTx = Math.floor((P.x + P.w / 2) / T);
      var cropsBefore = S.cropsWatered;
      Sys.update(S, dt, events);
      if (S.cropsWatered > cropsBefore) events.forEach(function (ev) { if (ev.target === 'crop' && ev.entity && ev.entity.watered) flt('Crop saved!  -1 water', ev.entity.x + T / 2, ev.entity.y - 20, '#1f9a50'); });
      Sys.popMessages(S).forEach(function (m) { toast(m.text, m.kind, m.kind === 'science' || m.kind === 'danger' ? 4.5 : 2.6); });
      Sys.sinkTilesToDrop(S).forEach(function (st) {
        if (L.tileMap.getTile(st.x, st.y)) {
          L.tileMap.setTile(st.x, st.y, null);
          L.tileMap.setTile(st.x, st.y + 1, 'sink3');
          addFx('dust', st.x * T + T / 2, st.y * T + T); addFx('crack', st.x * T + T / 2, (st.y + 1) * T); flt('-2 cm  ground sank for good', st.x * T + T / 2, st.y * T - 10, '#c8321f');
          if (!settings.reducedMotion) L.camera.triggerShake(4, 0.22);
          beep(110, 0.25, 'sawtooth', 0.06);
        }
      });
      updateTips(dt);
      L.toasts.forEach(function (t) { t.t -= dt; }); L.toasts = L.toasts.filter(function (t) { return t.t > 0; });
      L.fx.forEach(function (f) { f.t += dt; }); L.fx = L.fx.filter(function (f) { return f.t < 0.9; });
      L.floats.forEach(function (f) { f.t += dt; f.y -= 34 * dt; }); L.floats = L.floats.filter(function (f) { return f.t < 1.6; });
      L.camera.update(P, L.tileMap, dt, settings.reducedMotion);
    },
    draw: function (c) {
      if (!L) return;
      var sh = L.camera.shakeTime > 0 && !settings.reducedMotion ? L.camera.shakeMag : 0;
      var cx = Math.round(L.camera.x + (Math.random() - 0.5) * sh * 2), cy = Math.round(L.camera.y + (Math.random() - 0.5) * sh * 2);
      Art.drawBackground(c, L.json.biome, cx, W, H, L.time);
      var c0 = Math.max(0, Math.floor(cx / T)), c1 = Math.min(L.tileMap.width - 1, Math.ceil((cx + W) / T));
      var r0 = Math.max(0, Math.floor(cy / T)), r1 = Math.min(L.tileMap.height - 1, Math.ceil((cy + H) / T));
      var groundRow = L.json.groundRow || 9;
      for (var y = r0; y <= r1; y++) for (var x = c0; x <= c1; x++) {
        var tn = L.tileMap.getTile(x, y);
        if (!tn) { if (y >= groundRow) { c.fillStyle = y === groundRow ? 'rgba(40,24,14,.82)' : 'rgba(18,10,6,.92)'; c.fillRect(x * T - cx, y * T - cy, T + 1, T + 1); } continue; }
        Art.drawTile(c, tn, x * T - cx, y * T - cy);
        if (L.scanActive > 0 && tn.indexOf('sink') === 0) { c.fillStyle = 'rgba(232,72,60,' + (0.25 + 0.2 * Math.sin(L.time * 10)) + ')'; c.fillRect(x * T - cx, y * T - cy, T, T); }
      }
      drawAquiferLayer(c, cy, groundRow);
      for (var i = 0; i < L.entities.length; i++) {
        var e = L.entities[i]; if (!e.active || e.type === 'checkpoint') { if (e.type === 'checkpoint' && e.active) drawCheckpoint(c, e.x - cx, e.y - cy); continue; }
        var ex = Math.round(e.x - cx), ey = Math.round(e.y - cy); if (ex < -T * 2 || ex > W + T) continue;
        var name = e.type === 'pump' ? (e.off ? 'pump_off' : 'pump_on') : e.type === 'crop' ? (e.watered ? 'crop_green' : 'crop_dry') : e.type === 'dust' ? 'dust_devil' : e.type;
        var fr = Math.floor(L.time * (e.type === 'pump' ? 3 : 6));
        var bob = (e.type === 'drop' || e.type === 'chip') ? Math.sin(L.time * 4 + i) * 4 : 0;
        if (e.type === 'farmer') ey -= 36;
        if (e.type === 'dust' && e.calmed) c.globalAlpha = 0.35;
        Art.drawSprite(c, name, fr, ex, ey + bob, e.type === 'farmer');
        c.globalAlpha = 1;
        if ((e.type === 'pump' && !e.off) || (e.type === 'crop' && !e.watered)) {
          var P = L.player, near = Math.abs((P.x + P.w / 2) - (e.x + T / 2)) < T * 1.4 && Math.abs(P.y + P.h - (e.y + T)) < T;
          if (near) Art.keycap(c, keyName('E'), ex + 4, ey - 44);
        }
        drawLabel(c, e, ex, ey, cy, groundRow);
      }
      Player.drawPlayer(c, L.player, cx, cy);
      L.fx.forEach(function (f) { Art.fx(c, f.type, f.x - cx, f.y - cy, f.t); });
      L.floats.forEach(function (f) { c.globalAlpha = Math.min(1, (1.6 - f.t) * 2); Art.text(c, f.text, f.x - cx, f.y - cy, { size: 17, align: 'center', color: f.col, outline: 5, outlineColor: '#ffffff', shadow: false }); c.globalAlpha = 1; });
      if (L.scanActive > 0 && Art.radarSweep) {
        var p = 1 - L.scanActive / 3.5;
        if (!settings.reducedMotion) Art.radarSweep(c, W, H, p, L.json.biome);
        Art.drawSatellite(c, W * (0.1 + 0.8 * p), 120, 0.55);
      }
      var info = Sys.aquiferInfo(L.sys);
      Art.hud(c, { tank: L.sys.tank, tankMax: L.sys.tankMax, aquifer: info.value, redLine: info.redLine, hearts: L.player.hearts,
        chips: L.sys.chips, score: L.sys.score, level: L.json.name }, W, H);
      drawGoals(c);
      if (info.belowRed) {
        var pulse = 0.8 + 0.2 * Math.sin(L.time * 8), bw = 440;
        c.globalAlpha = pulse; Art.card(c, W / 2 - bw / 2, 84, bw, 40, { bg: '#c8321f', r: 20, flat: true }); c.globalAlpha = 1;
        Art.text(c, 'Water too low: ground is sinking! Turn pumps OFF', W / 2, 93, { size: 17, align: 'center', color: '#ffffff', shadow: false });
      }
      drawTip(c, cx, cy);
      drawToasts(c);
      if (L.idx === 0 && !isTouch) Art.text(c, '← → move  ·  SPACE jump  ·  E action  ·  P pause', 18, H - 26, { size: 13, color: '#ffffff', outline: 4, shadow: false });
    }
  };
  scenes.register('level', levelSceneObj);
  function idx0(i) { return i === 0; }

  function toast(text, kind, dur) {
    if (!L) return;
    if (L.toasts.some(function (t) { return t.text === text; })) return;
    L.toasts.push({ text: text, kind: kind || 'info', t: dur || 2.6 }); if (L.toasts.length > 3) L.toasts.shift();
  }
  function addFx(type, x, y) { if (L) L.fx.push({ type: type, x: x, y: y, t: 0 }); }
  function flt(text, x, y, col) { if (L) L.floats.push({ text: text, x: x, y: y, col: col, t: 0 }); }


  // Underground water drawn inside the ground (cross-section), linked to the HUD bar.
  function drawAquiferLayer(c, cy, groundRow) {
    var top = (groundRow + 1) * T - cy, bottom = H, depth = bottom - top; if (depth <= 8) return;
    var info = Sys.aquiferInfo(L.sys), lvl = Math.max(0, Math.min(100, info.value)) / 100, wy = bottom - depth * lvl;
    var safeY = bottom - depth * info.redLine / 100;
    c.save(); c.globalAlpha = 0.55;
    c.fillStyle = info.belowRed ? '#2a6fb8' : '#2f8fe6';
    c.beginPath(); c.moveTo(0, bottom);
    for (var x = 0; x <= W; x += 16) c.lineTo(x, wy + Math.sin(x / 40 + L.time * 2) * 3);
    c.lineTo(W, bottom); c.closePath(); c.fill();
    c.globalAlpha = 1; c.strokeStyle = '#ffd23f'; c.lineWidth = 3; c.setLineDash([12, 8]);
    c.beginPath(); c.moveTo(0, safeY); c.lineTo(W, safeY); c.stroke(); c.setLineDash([]);
    Art.text(c, 'WATER UNDERGROUND', 12, Math.min(bottom - 22, wy + 4), { size: 13, color: '#ffffff', outline: 4, outlineColor: '#1b3d6e', shadow: false });
    Art.text(c, 'safe line', W - 12, safeY - 18, { size: 12, align: 'right', color: '#ffd23f', outline: 4, outlineColor: '#3a2a10', shadow: false });
    c.restore();
  }
  // Small tags above objects near the player, so every object explains itself.
  function drawLabel(c, e, ex, ey, cy, groundRow) {
    var P = L.player, d = Math.abs((P.x + P.w / 2) - (e.x + T / 2)) / T;
    if (e.type === 'pump' && !e.off) {   // water flowing UP the pipe, out of the ground
      var px = ex + 10, y0 = (groundRow + 1) * T - cy + 40, y1 = ey + T - 6;
      c.strokeStyle = 'rgba(70,80,100,.85)'; c.lineWidth = 6; c.beginPath(); c.moveTo(px, y0); c.lineTo(px, y1); c.stroke();
      for (var k = 0; k < 4; k++) { var f = ((L.time * 1.4 + k / 4) % 1), yy = y0 + (y1 - y0) * f; c.fillStyle = '#6fc0ff'; c.beginPath(); c.arc(px, yy, 4, 0, Math.PI * 2); c.fill(); }
    }
    if (d > 6) return;
    var txt = null, col = '#1c2233';
    if (e.type === 'pump') { txt = e.off ? 'OFF ✔' : 'PUMP: pulls water out'; col = e.off ? '#1f7a35' : '#a33a2c'; }
    else if (e.type === 'crop' && !e.watered) txt = 'Thirsty: needs 1 water';
    else if (e.type === 'drop') txt = '+1 water';
    else if (e.type === 'chip') txt = e.fact === 'qc' ? 'data chip?' : 'NISAR data chip';
    else if (e.type === 'dust' && !e.calmed) { txt = 'Dust devil: steals water'; col = '#8a5a12'; }
    else if (e.type === 'flag') txt = 'GOAL';
    if (!txt) return;
    c.font = '800 13px "Baloo 2", sans-serif'; var w = c.measureText(txt).width + 16, lx = ex + T / 2 - w / 2, ly = ey - (e.type === 'farmer' ? 0 : 26) - (e.type === 'drop' || e.type === 'chip' ? 10 : 0);
    c.globalAlpha = Math.max(0, Math.min(1, (6 - d) / 2));
    c.fillStyle = 'rgba(255,255,255,.92)'; c.beginPath(); c.roundRect ? c.roundRect(lx, ly, w, 20, 10) : c.rect(lx, ly, w, 20); c.fill();
    Art.text(c, txt, ex + T / 2, ly + 2, { size: 13, align: 'center', color: col, shadow: false });
    c.globalAlpha = 1;
  }
  function drawCheckpoint(c, x, y) {
    c.fillStyle = '#2e3650'; c.fillRect(x + 20, y + 4, 6, T - 4);
    c.fillStyle = '#ffd23f'; c.beginPath(); c.moveTo(x + 26, y + 6); c.lineTo(x + 44, y + 13); c.lineTo(x + 26, y + 20); c.fill();
  }
  function drawGoals(c) {
    var S = L.sys, y = 84;
    Art.card(c, 14, y, 220, 64, { bg: 'rgba(20,26,44,.72)', r: 14, flat: true });
    Art.text(c, 'Pumps off  ' + S.pumpsOff + ' / ' + S.pumpsTotal, 28, y + 8, { size: 14, color: S.pumpsOff >= S.pumpsTotal ? '#7dff9c' : '#ffffff', shadow: false });
    Art.text(c, 'Crops saved ' + S.cropsWatered + ' / ' + S.cropsTotal, 28, y + 26, { size: 14, color: S.cropsWatered >= S.cropsTotal ? '#7dff9c' : '#ffffff', shadow: false });
    var cm = Sys.aquiferInfo(S).cmSunk;
    Art.text(c, 'Ground sunk  ' + cm + ' cm', 28, y + 44, { size: 14, color: cm > 0 ? '#ff9d8f' : '#ffffff', shadow: false });
  }
  function drawToasts(c) {
    var y = Sys.aquiferInfo(L.sys).belowRed ? 134 : 84;
    L.toasts.forEach(function (t) {
      c.font = '800 17px "Baloo 2", "Trebuchet MS", sans-serif';
      var w = Math.min(560, c.measureText(t.text).width + 40), x = W - 14 - w;
      var bg = { good: 'rgba(34,120,70,.92)', warn: 'rgba(170,100,20,.94)', danger: 'rgba(180,40,32,.94)', science: 'rgba(30,70,160,.94)', info: 'rgba(20,26,44,.9)' }[t.kind] || 'rgba(20,26,44,.9)';
      c.globalAlpha = Math.min(1, t.t * 3);
      Art.card(c, x, y, w, 40, { bg: bg, r: 20, flat: true });
      wrapText(c, t.text, x + w / 2, y + 9, w - 30, 17);
      c.globalAlpha = 1; y += 50;
    });
  }
  function wrapText(c, s, x, y, maxW, size) { // one line, shrink if needed
    var sz = size; c.font = '800 ' + sz + 'px "Baloo 2", sans-serif';
    while (c.measureText(s).width > maxW && sz > 11) { sz--; c.font = '800 ' + sz + 'px "Baloo 2", sans-serif'; }
    Art.text(c, s, x, y + (size - sz) / 2, { size: sz, align: 'center', color: '#fff', shadow: false });
  }

  // ---------- tutorial tips (data from the level JSON) ----------
  function tipDone(t) {
    var P = L.player, S = L.sys, px = (P.x + P.w / 2) / T;
    switch (t.until) {
      case 'moved': return Math.abs(P.x - L.spawnX) > T * 3;
      case 'jumped': return L.jumpedOnce;
      case 'tank3': return S.tank >= 3;
      case 'pump': return S.pumpsOff >= 1;
      case 'crop': return S.cropsWatered >= 1;
      case 'time5': return t.shownT > 5;
      case 'pass': return px > t.x + 7;
      default: return t.shownT > 5;
    }
  }
  function currentTip() {
    var px = (L.player.x + L.player.w / 2) / T;
    for (var i = 0; i < L.tips.length; i++) { var t = L.tips[i]; if (!t.done && px > t.x + 12) t.done = true; if (!t.done && px >= t.x - 1) return t; }
    return null;
  }
  function updateTips(dt) {
    L.tips.forEach(function (t) { if (!t.done && tipDone(t)) { t.done = true; if (t.shownT > 0) beep(880, 0.06, 'sine', 0.03); } });
    var t = currentTip(); if (t) t.shownT += dt;
  }
  function drawTip(c, cx, cy) {
    var t = currentTip(); if (!t) return;
    var keys = (t.keys || []).map(keyName);
    if (t.hud) { Art.tip(c, W / 2, 96 + 118, t.text, keys); c.strokeStyle = '#ffd23f'; c.lineWidth = 4; c.beginPath(); c.moveTo(W / 2, 112); c.lineTo(W / 2, 80); c.stroke(); return; }
    var P = L.player; Art.tip(c, Math.round(P.x + P.w / 2 - cx), Math.round(P.y - cy - 14), t.text, keys);
  }

  // ---------- PAUSE ----------
  var pauseOpt = 0, pauseCool = 0;
  var PAUSE_ITEMS = function () { return ['Resume', 'Sound: ' + (settings.sound ? 'ON' : 'OFF'), 'Reduced motion: ' + (settings.reducedMotion ? 'ON' : 'OFF'), 'Restart level', 'Valley map']; };
  scenes.register('pause', {
    enter: function () { pauseOpt = 0; pauseCool = 0.2; },
    update: function (dt, inp) {
      pauseCool = Math.max(0, pauseCool - dt);
      if (inp.pausePressed && pauseCool <= 0) { scenes.go('level', { resume: true }); return; }
      if (pauseCool <= 0 && (inp.left || inp.right)) { pauseOpt = (pauseOpt + (inp.right ? 1 : 4)) % 5; pauseCool = 0.18; }
      var tap = takeTap(); if (tap) { var k = Math.floor((tap.y - 170) / 52); if (k >= 0 && k < 5) pauseOpt = k; }
      if (inp.jumpPressed || inp.actionPressed || tap) {
        if (pauseOpt === 0) scenes.go('level', { resume: true });
        else if (pauseOpt === 1) { settings.sound = !settings.sound; saveSettings(); }
        else if (pauseOpt === 2) { settings.reducedMotion = !settings.reducedMotion; saveSettings(); }
        else if (pauseOpt === 3) startLevel(L.idx, true);
        else scenes.go('map');
      }
    },
    draw: function (c) {
      if (L) levelSceneObj.draw(c);
      c.fillStyle = 'rgba(12,16,30,.72)'; c.fillRect(0, 0, W, H);
      Art.text(c, 'Paused', W / 2, 96, { size: 48, align: 'center', color: '#fff', outline: 8 });
      PAUSE_ITEMS().forEach(function (it, i) {
        Art.card(c, W / 2 - 170, 170 + i * 52, 340, 42, { bg: i === pauseOpt ? '#ffd23f' : 'rgba(255,255,255,.12)', r: 21, flat: true });
        Art.text(c, it, W / 2, 178 + i * 52, { size: 20, align: 'center', color: i === pauseOpt ? '#1c2233' : '#fff', shadow: false });
      });
    }
  });

  // ---------- REPORT CARD: what you did -> what happened -> what NISAR really measured ----------
  var rep = null, repT = 0, repMenu = makeMenu();
  function repItems() {
    var idx = rep.levelIdx, last = idx === LEVELS.length - 1, items = [];
    if (last) items.push({ label: 'Finish  ★', go: function () { scenes.go('finale'); } });
    else if (isUnlocked(idx + 1)) items.push({ label: 'Next valley  ▶', go: function () { mapIdx = idx + 1; startLevel(idx + 1); } });
    items.push({ label: '↻  Try again', go: function () { startLevel(idx, true); } });
    items.push({ label: 'Valley map', go: function () { scenes.go('map'); } });
    items.push({ label: 'Real NISAR map ↗', go: function () { openPage('../atlas.html#' + (ATLAS_ID[rep.json.id] || '')); } });
    return items;
  }
  scenes.register('report', {
    enter: function (p) { rep = p; repT = 0; repMenu.sel = 0; repMenu.pl = repMenu.pr = true; },
    update: function (dt, inp) {
      repT += dt; var tap = takeTap(); if (repT < 0.9) return;
      var it = menuUpdate(repMenu, repItems(), inp, tap);
      if (it) { beep(600, 0.12, 'triangle'); it.go(); }
    },
    draw: function (c) { drawReport(c); }
  });
  function reportRows(R) {
    var rows = [];
    rows.push({ icon: R.pumpsOff ? 'pump_off' : 'pump_on', ok: R.pumpsOff === R.pumpsTotal,
      a: 'Switched off ' + R.pumpsOff + ' of ' + R.pumpsTotal + ' pumps',
      b: R.pumpsOff === R.pumpsTotal ? '→ no more water pulled out, so it could refill' : '→ ' + (R.pumpsTotal - R.pumpsOff) + ' kept draining the water underground' });
    rows.push({ icon: R.cropsWatered ? 'crop_green' : 'crop_dry', ok: R.cropsWatered === R.cropsTotal,
      a: 'Saved ' + R.cropsWatered + ' of ' + R.cropsTotal + ' crops with rainwater',
      b: '→ farms that get rain need to pump less' });
    rows.push({ icon: 'drop', ok: R.drops > 0, a: 'Caught ' + (R.drops || 0) + ' raindrops',
      b: R.dustHits ? '→ dust devils stole water ' + R.dustHits + ' time' + (R.dustHits > 1 ? 's' : '') : '→ rain is the water you can use without pumping' });
    rows.push({ icon: 'chip', ok: R.chips === R.chipsTotal, a: 'Collected ' + R.chips + ' of ' + R.chipsTotal + ' NISAR data chips',
      b: R.qcFound ? '→ and you spotted the bad reading, like our quality check' : '→ each chip is a real NISAR measurement' });
    return rows;
  }
  function drawReport(c) {
    var r = rep.result, R = r.report, rows = reportRows(R);
    Art.drawBackground(c, rep.json.biome, repT * 20, W, H, repT);
    c.fillStyle = 'rgba(10,14,28,.55)'; c.fillRect(0, 0, W, H);
    Art.card(c, 24, 12, W - 48, H - 24, { bg: '#fff7e8', r: 24 });
    Art.text(c, rep.json.name + ': what happened?', W / 2, 22, { size: 28, align: 'center', color: '#1c2233', shadow: false });
    for (var s = 0; s < 3; s++) { var pop = Math.min(1, Math.max(0, (repT - 0.3 - s * 0.25) * 4)); if (pop > 0) Art.icon(c, 'star', W / 2 - 84 + s * 56, 62, 48 * pop, r.stars[s]); }
    var labels = ['Reached the flag', 'Water stayed above the safe line', 'All NISAR data chips'];
    labels.forEach(function (lb, i) { Art.text(c, (r.stars[i] ? '★ ' : '☆ ') + lb, 60 + i * 290, 116, { size: 14, color: r.stars[i] ? '#1f7a35' : '#a33a2c', shadow: false }); });
    Art.text(c, 'Score ' + r.score, W - 52, 26, { size: 22, align: 'right', color: '#1c2233', shadow: false });

    // left: what you did -> what it caused
    Art.text(c, 'What you did', 56, 146, { size: 16, color: '#2f6fb8', shadow: false });
    rows.forEach(function (row, i) {
      var y = 170 + i * 52;
      c.save(); c.translate(56, y); c.scale(0.85, 0.85); Art.drawSprite(c, row.icon, 0, 0, 0, false); c.restore();
      Art.text(c, row.a, 106, y + 2, { size: 16, color: '#1c2233', shadow: false });
      Art.text(c, row.b, 106, y + 22, { size: 13, color: row.ok ? '#1f7a35' : '#8a5a1c', shadow: false });
    });

    // right: the water curve + the ground result
    var gx = 520, gy = 168, gw = 384, gh = 80, cur = R.aquiferCurve || [];
    Art.text(c, 'Water underground during your run', gx, 146, { size: 16, color: '#2f6fb8', shadow: false });
    c.fillStyle = '#eaf2fb'; c.fillRect(gx, gy, gw, gh);
    var ry = gy + gh - gh * R.redLine / 100;
    c.fillStyle = 'rgba(200,50,31,.10)'; c.fillRect(gx, ry, gw, gy + gh - ry);
    c.strokeStyle = '#e8b33a'; c.setLineDash([8, 6]); c.lineWidth = 2; c.beginPath(); c.moveTo(gx, ry); c.lineTo(gx + gw, ry); c.stroke(); c.setLineDash([]);
    if (cur.length > 1) { c.strokeStyle = '#2f8fe6'; c.lineWidth = 3; c.beginPath(); cur.forEach(function (v, i) { var x = gx + gw * i / (cur.length - 1), y = gy + gh - gh * v / 100; if (i) c.lineTo(x, y); else c.moveTo(x, y); }); c.stroke(); }
    Art.text(c, 'safe line', gx + gw - 4, ry - 16, { size: 11, align: 'right', color: '#b98516', shadow: false });
    Art.text(c, R.secondsBelowSafe ? 'Below the safe line for ' + R.secondsBelowSafe + ' s' : 'Never below the safe line', gx, gy + gh + 4, { size: 12, color: R.secondsBelowSafe ? '#a33a2c' : '#1f7a35', shadow: false });

    Art.card(c, gx, 274, gw, 104, { bg: '#ffffff', r: 14, flat: true });
    Art.text(c, 'Your valley sank', gx + 16, 282, { size: 13, color: '#4a5468', shadow: false });
    Art.text(c, R.cmSunk + ' cm', gx + 16, 298, { size: 32, color: R.cmSunk > 0 ? '#c8321f' : '#1f7a35', shadow: false });
    Art.text(c, 'in this game', gx + 16, 338, { size: 12, color: '#4a5468', shadow: false });
    Art.text(c, 'The real valley (NISAR)', gx + 200, 282, { size: 13, color: '#4a5468', shadow: false });
    Art.text(c, (R.realFactCm != null ? Number(R.realFactCm).toFixed(1) : '?') + ' cm', gx + 200, 298, { size: 32, color: '#1b5fae', shadow: false });
    Art.text(c, 'in 100 days, measured in 2026', gx + 200, 338, { size: 12, color: '#4a5468', shadow: false });
    Art.text(c, 'Sunk ground does not come back up.', gx + 16, 356, { size: 12, color: '#1c2233', shadow: false });

    // the one-line lesson
    Art.card(c, 56, 388, W - 112, 50, { bg: R.cmSunk > 0 ? '#ffe1d9' : '#dff3e2', r: 14, flat: true });
    wrapBlock(c, R.oneLine, 72, 394, W - 144, 14, '#1c2233');
    if (repT > 0.9) menuDraw(c, repMenu, repItems(), 450, repT, false, true);
    Art.text(c, R.calibration, W / 2, H - 30, { size: 10, align: 'center', color: '#8a90a0', shadow: false });
  }

  // ---------- FINALE: all four valleys, tie back to the real project ----------
  var finT = 0, finMenu = makeMenu();
  var FIN_ITEMS = [
    { label: 'Explore the real NISAR map ↗', go: function () { openPage('../atlas.html'); } },
    { label: 'NISAR Vision home ↗', go: function () { openPage('../index.html'); } },
    { label: 'Play again', go: function () { scenes.go('map'); } }
  ];
  scenes.register('finale', {
    enter: function () { finT = 0; finMenu.sel = 0; finMenu.pl = finMenu.pr = true; jingle([523, 659, 784, 1047, 1319]); },
    update: function (dt, inp) {
      finT += dt; var tap = takeTap(); if (finT < 1) return;
      var it = menuUpdate(finMenu, FIN_ITEMS, inp, tap); if (it) { beep(600, 0.12, 'triangle'); it.go(); }
    },
    draw: function (c) {
      Art.drawBackground(c, 'mexico', finT * 20, W, H, finT);
      c.fillStyle = 'rgba(10,14,28,.6)'; c.fillRect(0, 0, W, H);
      Art.text(c, 'You visited 4 sinking valleys!', W / 2, 18, { size: 34, align: 'center', color: '#fff', outline: 7 });
      var prog = loadProgress(), total = 0;
      Art.card(c, 120, 74, W - 240, 234, { bg: '#fff7e8', r: 18 });
      Art.text(c, 'Valley', 150, 86, { size: 14, color: '#6b7286', shadow: false });
      Art.text(c, 'Your stars', 470, 86, { size: 14, align: 'center', color: '#6b7286', shadow: false });
      Art.text(c, 'Real sinking (NISAR)', W - 150, 86, { size: 14, align: 'right', color: '#6b7286', shadow: false });
      LEVELS.forEach(function (lv, i) {
        var y = 116 + i * 42, st = prog[lv.id] || 0, d = levelData[lv.id]; total += st;
        Art.text(c, lv.name + ', ' + lv.place, 150, y, { size: 18, color: '#1c2233', shadow: false });
        for (var k = 0; k < 3; k++) Art.icon(c, 'star', 426 + k * 30, y - 2, 26, k < st);
        Art.text(c, (d && d.nisar ? Number(d.nisar.realFactCm).toFixed(1) : '?') + ' cm / 100 days', W - 150, y, { size: 18, align: 'right', color: '#1b5fae', shadow: false });
      });
      Art.text(c, 'Total: ' + total + ' / 12 stars', W / 2, 278, { size: 15, align: 'center', color: '#1c2233', shadow: false });
      var msg = ['Everything you saw is real. NISAR, a NASA-ISRO radar satellite, measured these', 'valleys sinking in 2026. Pumping too much groundwater is the main cause,', 'and using less of it is how people slow it down.'];
      msg.forEach(function (ln, k) { Art.text(c, ln, W / 2, 322 + k * 24, { size: 17, align: 'center', color: '#ffffff', shadow: false }); });
      if (finT > 1) menuDraw(c, finMenu, FIN_ITEMS, 408, finT, true);
    }
  });
  function wrapBlock(c, s, x, y, maxW, size, col) {
    if (!s) return; c.font = '800 ' + size + 'px "Baloo 2", sans-serif';
    var words = String(s).split(' '), line = '', yy = y;
    words.forEach(function (w) { var test = line ? line + ' ' + w : w; if (c.measureText(test).width > maxW && line) { Art.text(c, line, x, yy, { size: size, color: col, shadow: false }); line = w; yy += size + 5; } else line = test; });
    if (line) Art.text(c, line, x, yy, { size: size, color: col, shadow: false });
  }

  if (/[?&]debug/.test(location.search)) window.AquiferDebug = { scenes: scenes, getL: function () { return L; } };
  function boot() {
    scenes.go('title');
    LEVELS.forEach(function (lv) { fetchLevel(lv.id).catch(function () { return null; }); });
    Engine.startLoop(function (dt) { input.update(); scenes.update(dt, input); }, function () { scenes.draw(ctx); });
  }
  if (Art && Art.ready && typeof Art.ready.then === 'function') Art.ready.then(boot, boot); else boot();
})();
